// Some portions generated by Co-Pilot
"use client";

import React, { useId, useState } from "react";
import { useTranslations } from "next-intl";
import PieChart, { type PieChartPoint } from "@/components/Dashboard/PieChart";
import { capitalize } from "@/utils/capitalize";
import type {
  PlatformBreakdownRow as Row,
  PlatformBreakdownStats,
} from "@/utils/fetchPlatformBreakdown";

const SOURCE_URL = "https://api.adoptium.net/v3/assets/feature_releases";
const COLORS = [
  "#2caffe",
  "#feae62",
  "#6c6de3",
  "#a259f7",
  "#f67280",
  "#43e97b",
];

type Dimension = "os" | "architecture" | "imageType" | "packageType";
type PackageType = "archive" | "installer";
type Filters = Record<Dimension, string[]>;

const DIMENSIONS: Dimension[] = [
  "os",
  "architecture",
  "imageType",
  "packageType",
];
const PACKAGE_TYPES: PackageType[] = ["archive", "installer"];
const EMPTY_FILTERS: Filters = {
  os: [],
  architecture: [],
  imageType: [],
  packageType: [],
};

const imageGroup = (type: string) =>
  type === "jdk" || type === "jre" ? type : "other";

const rowKey = (row: Row, dimension: Exclude<Dimension, "packageType">) =>
  dimension === "imageType" ? imageGroup(row.imageType) : row[dimension];

// Applies every active filter except the one belonging to the chart being built,
// so each chart keeps showing its own alternatives.
const matches = (row: Row, filters: Filters, except: Dimension) =>
  (["os", "architecture", "imageType"] as const).every(
    (dimension) =>
      dimension === except ||
      !filters[dimension].includes(rowKey(row, dimension)),
  );

const countByDimension = (
  rows: Row[],
  filters: Filters,
  dimension: Dimension,
): Record<string, number> => {
  const counts: Record<string, number> = {};
  const add = (key: string, value: number) => {
    counts[key] = (counts[key] ?? 0) + value;
  };
  for (const row of rows) {
    if (!matches(row, filters, dimension)) continue;
    if (dimension === "packageType") {
      PACKAGE_TYPES.forEach((type) => add(type, row[type]));
    } else {
      add(
        rowKey(row, dimension),
        PACKAGE_TYPES.reduce(
          (total, type) =>
            total + (filters.packageType.includes(type) ? 0 : row[type]),
          0,
        ),
      );
    }
  }
  for (const key of filters[dimension]) counts[key] ??= 0;
  return counts;
};

const toPieData = (
  counts: Record<string, number>,
  label: (key: string) => string,
  excluded: string[],
): PieChartPoint[] =>
  Object.entries(counts)
    .filter(([id, y]) => y > 0 || excluded.includes(id))
    .sort(([, a], [, b]) => b - a)
    .map(([id, y]) => ({
      id,
      name: label(id),
      y,
      visible: !excluded.includes(id),
    }));

const osLabel = (os: string) => (os === "aix" ? "AIX" : capitalize(os));

interface PlatformBreakdownProps {
  stats: PlatformBreakdownStats;
}

const PlatformBreakdown: React.FC<PlatformBreakdownProps> = ({ stats }) => {
  const t = useTranslations("ModernPages.stats");
  const tCommon = useTranslations("ModernPages.common");
  const selectId = useId();
  const [version, setVersion] = useState("");
  const [filters, setFilters] = useState<Filters>(EMPTY_FILTERS);
  const versions = [...new Set(stats.rows.map((row) => row.version))].sort(
    (a, b) => a - b,
  );
  const rows = version
    ? stats.rows.filter((row) => String(row.version) === version)
    : stats.rows;

  const labels: Record<Dimension, (key: string) => string> = {
    os: osLabel,
    architecture: (arch) => arch,
    imageType: (type) => (type === "other" ? t("other") : type.toUpperCase()),
    packageType: (type) => t(type as PackageType),
  };
  const titles: Record<Dimension, string> = {
    os: t("by-os"),
    architecture: t("by-arch"),
    imageType: t("by-image-type"),
    packageType: t("by-package"),
  };

  const toggleFilter = (dimension: Dimension, key: string) =>
    setFilters((current) => ({
      ...current,
      [dimension]: current[dimension].includes(key)
        ? current[dimension].filter((value) => value !== key)
        : [...current[dimension], key],
    }));
  const hasFilters = Object.values(filters).some((values) => values.length > 0);

  return (
    <section className="min-w-0 rounded-2xl border border-white/10 bg-white/[0.025] p-4 sm:p-6">
      <div className="mb-4 flex flex-wrap items-end justify-between gap-4">
        <div>
          <h2 className="mb-1 text-xl font-semibold">{t("platform-title")}</h2>
          <p className="mb-0 text-sm text-grey">{t("platform-description")}</p>
          <p className="mb-0 text-sm text-grey">{t("platform-hint")}</p>
        </div>
        <div className="flex flex-wrap items-end gap-3">
          {hasFilters && (
            <button
              type="button"
              className="min-h-10 rounded-lg border border-white/15 px-3 py-2 text-sm hover:border-pink focus:outline-none focus:ring-2 focus:ring-pink"
              onClick={() => setFilters(EMPTY_FILTERS)}
            >
              {t("clear-filters")}
            </button>
          )}
          <div className="flex flex-col gap-1">
            <label htmlFor={selectId} className="text-xs font-medium text-grey">
              {t("version")}
            </label>
            <select
              id={selectId}
              className="min-h-10 rounded-lg border border-white/15 bg-[#1c1040] px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-pink"
              value={version}
              onChange={(event) => setVersion(event.target.value)}
            >
              <option value="">{tCommon("all")}</option>
              {versions.map((v) => (
                <option key={v} value={v}>
                  JDK {v}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>
      <div className="grid min-w-0 gap-6 lg:grid-cols-2">
        {DIMENSIONS.map((dimension) => (
          <div key={dimension} className="min-w-0">
            <PieChart
              data={toPieData(
                countByDimension(rows, filters, dimension),
                labels[dimension],
                filters[dimension],
              )}
              name={titles[dimension]}
              showInLegend
              dataLabels
              colors={COLORS}
              sourceUrl={SOURCE_URL}
              onPointClick={({ id, name }) =>
                toggleFilter(dimension, id ?? name)
              }
            />
          </div>
        ))}
      </div>
    </section>
  );
};

export default PlatformBreakdown;
